from decimal import Decimal, ROUND_HALF_UP
value = Decimal(str(data['principal'])) * (1 + Decimal(str(data['rate'])) / 100) ** int(data['years'])
result = {'value': float(value.quantize(Decimal('0.01'), ROUND_HALF_UP)), 'values': {'principal': data['principal'], 'rate': data['rate'], 'years': data['years']}}
